                        : 'bg-white border border-cream-200 text-brown-900 rounded-tl-none'
                    }`}>
                    {msg.content}
                  </div>
                </div>
              ))}
            </div>

            <div className="p-3 bg-white border-t border-cream-200">
              <div className="relative">
                <input 
                  type="text" 
                  value={messageInput}
                  onChange={(e) => setMessageInput(e.target.value)}
                  placeholder="Mensagem ou @IA-Lab..." 
                  className="w-full pl-4 pr-10 py-2.5 bg-cream-100/50 border border-cream-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500/20 text-sm placeholder:text-brown-800/30"
                  onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                />
                <button 
                  onClick={handleSendMessage}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-orange-500 hover:text-orange-600 p-1"
                >
                  <Send size={16} />
                </button>
              </div>
            </div>
          </Card>
        </div>

      </div>
    </div>
  );
};

