import { MemoryNode, MemoryEdge, GraphContext } from '../types';

// Estrutura de armazenamento em memória:
// Cache[CompanyId][ScopeKey] -> { nodes, edges }
// ScopeKey pode ser "global", "squad_{id}" ou "user_{id}"
type GraphStore = {
  [companyId: string]: {
    [scopeKey: string]: {
      nodes: MemoryNode[];
      edges: MemoryEdge[];
    };
  };
};

