            <div className="flex items-center justify-between mb-4">
              <span className="font-bold text-brown-900">Outubro 2023</span>
              <CalendarIcon size={16} className="text-orange-500" />
            </div>
            {/* Simple CSS Grid Calendar Visualization */}
            <div className="grid grid-cols-7 text-center text-xs gap-y-2">
              {['D','S','T','Q','Q','S','S'].map(d => <span key={d} className="text-brown-800/40 font-medium">{d}</span>)}
              {/* Offset days */}
              {[...Array(2)].map((_, i) => <span key={`empty-${i}`} />)}
              {/* Days */}
              {[...Array(31)].map((_, i) => {
                const day = i + 1;
                const isToday = day === 12;
                const hasEvent = [15, 18].includes(day);
                return (
                  <div key={day} className="flex items-center justify-center">
                    <span className={`w-7 h-7 flex items-center justify-center rounded-full text-brown-800 
                      ${isToday ? 'bg-brown-900 text-white shadow-md' : 'hover:bg-cream-100'}
                      ${hasEvent && !isToday ? 'border border-orange-200 bg-orange-50' : ''}
                    `}>
                      {day}
                    </span>
                  </div>
                )
              })}
            </div>
          </Card>

          {/* Chat */}
          <Card className="flex-1 flex flex-col min-h-0 p-0 overflow-hidden border-orange-100/50">
            <div className="p-4 border-b border-cream-200 bg-white">
              <h3 className="font-semibold text-brown-900">Chat do Squad</h3>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-cream-50/30">
              {MOCK_CHAT.map(msg => (
                <div key={msg.id} className={`flex flex-col ${msg.isAI ? 'items-start' : msg.sender === 'Ana' ? 'items-end' : 'items-start'}`}>
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`text-xs font-bold ${msg.isAI ? 'text-orange-600' : 'text-brown-800/60'}`}>{msg.sender}</span>
                    <span className="text-[10px] text-brown-800/30">{msg.timestamp}</span>
                  </div>
                  <div className={`p-3 rounded-2xl max-w-[90%] text-sm
                    ${msg.isAI 
                      ? 'bg-orange-50 border border-orange-100 text-brown-900 rounded-tl-none shadow-sm' 
                      : msg.sender === 'Ana' 
                        ? 'bg-brown-800 text-white rounded-tr-none shadow-sm' 
                        : 'bg-white border border-cream-200 text-brown-900 rounded-tl-none'
                    }`}>
                    {msg.content}
                  </div>
                </div>
              ))}
            </div>

            <div className="p-3 bg-white border-t border-cream-200">
              <div className="relative">
                <input 
                  type="text" 
                  value={messageInput}
                  onChange={(e) => setMessageInput(e.target.value)}
                  placeholder="Mensagem ou @IA-Lab..." 
                  className="w-full pl-4 pr-10 py-2.5 bg-cream-100/50 border border-cream-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500/20 text-sm placeholder:text-brown-800/30"
                  onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                />
                <button 
                  onClick={handleSendMessage}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-orange-500 hover:text-orange-600 p-1"
                >
                  <Send size={16} />
                </button>
              </div>
            </div>
          </Card>
        </div>

      </div>
    </div>
  );
};

