import { GoogleGenAI } from "@google/genai";
import { MemoryNode } from "../types";

export class AIService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  async getSquadAdvice(
    message: string, 
    history: { sender: string; content: string }[],
    squadMemory: MemoryNode[],
    context: { companyId: string; squadId: string }
  ) {
    // Formatting context for the model
    const memoryContext = squadMemory.map(n => `- ${n.label} (${n.type}): ${JSON.stringify(n.data || '')}`).join('\n');

    const systemInstruction = `
      Você é a IA do Lab de Inovação Jurídica da USP.
      Contexto Multitenant: Empresa: ${context.companyId}, Squad: ${context.squadId}.
      Memória Atual do Squad (Conhecimento Acumulado):
      ${memoryContext}

      Sua função é auxiliar em dúvidas complexas de Direito Digital, Legal Design e Inovação.
      Use o modo de pensamento profundo para analisar as implicações jurídicas e técnicas das solicitações.
      Sempre cite a memória do squad quando relevante.
    `;

    try {
      const response = await this.ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: [
          { role: 'user', parts: [{ text: message }] }
        ],
        config: {
          systemInstruction,
          thinkingConfig: { thinkingBudget: 32768 }
        },
      });

      return response.text;
    } catch (error) {
      console.error("AI Service Error:", error);
      return "Desculpe, tive um problema ao processar sua solicitação complexa. Tente novamente em instantes.";
    }
  }
}

