import React, { useState, useRef, useEffect } from 'react';
import { Card } from '../components/ui/Card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../components/ui/Tabs';
import { Button } from '../components/ui/Button';
import { Badge } from '../components/ui/Badge';
import { Plus, MoreHorizontal, Send, Calendar as CalendarIcon, Target, Layout, Network, BrainCircuit, Share2, Sparkles, Loader2 } from 'lucide-react';
import { MOCK_TASKS, MOCK_OKRS } from '../constants';
import { useMemory } from '../contexts/MemoryContext';
import { aiService } from '../services/AIService';
import { ChatMessage } from '../types';

export const SquadPage: React.FC = () => {
  const [activeTab, setActiveTab] = useState('kanban');
  const [messageInput, setMessageInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { id: '1', sender: 'Ana', content: 'Pessoal, atualizei o board com a pesquisa de campo.', timestamp: '10:30', isAI: false },
    { id: '2', sender: '@IA-Lab', content: 'Ótimo, Ana! Com base nos dados inseridos, sugiro focar na dor de "gestão de prazos" para o próximo sprint.', timestamp: '10:31', isAI: true },
  ]);
  const [isThinking, setIsThinking] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const { nodes, edges, isLoading, addConcept, currentUser } = useMemory();
  const [newConcept, setNewConcept] = useState('');

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [chatHistory, isThinking]);

  const handleSendMessage = async () => {
    if (!messageInput.trim() || isThinking) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      sender: currentUser.name,
      content: messageInput,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isAI: false
    };

    setChatHistory(prev => [...prev, userMessage]);
    setMessageInput('');
    setIsThinking(true);

    // Call Gemini with thinking mode and squad memory
    const aiResponse = await aiService.getSquadAdvice(
      messageInput,
      chatHistory,
      nodes,
      { companyId: currentUser.companyId, squadId: currentUser.squadId }
    );

    const aiMessage: ChatMessage = {
      id: (Date.now() + 1).toString(),
      sender: '@IA-Lab (Pro Thinking)',
      content: aiResponse || "Houve um erro no processamento.",
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isAI: true
    };

    setChatHistory(prev => [...prev, aiMessage]);
    setIsThinking(false);
  };

  const handleAddConcept = () => {
    if (!newConcept.trim()) return;
    addConcept(newConcept, 'concept');
    setNewConcept('');
  };

  const getConnections = (nodeId: string) => {
    return edges.filter(e => e.source === nodeId || e.target === nodeId).map(e => {
      const otherId = e.source === nodeId ? e.target : e.source;
      const otherNode = nodes.find(n => n.id === otherId);
      return { relationship: e.relationship, label: otherNode?.label || 'Unknown' };
    });
  };

  return (
    <div className="flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500 min-h-[calc(100vh-8rem)]">
